import{_ as i,o as n,c as a,ai as l}from"./chunks/framework.BxxKhjs3.js";const g=JSON.parse('{"title":"HarmonyOS 文本展开折叠功能 - 从入门到精通","description":"","frontmatter":{},"headers":[],"relativePath":"HarmonyOS 最佳实践/14-文本展开折叠/14-文本展开折叠.md","filePath":"HarmonyOS 最佳实践/14-文本展开折叠/14-文本展开折叠.md","lastUpdated":1750695195000,"__rawMarkdown":"# HarmonyOS 文本展开折叠功能 - 从入门到精通\\n\\n## 📚 前言\\n\\n在我们日常使用的社交媒体应用中，你是否注意到这样的场景：当一条评论或动态的文字内容过长时，会显示\\"...展开\\"的按钮，点击后可以查看完整内容，再次点击\\"收起\\"又能折叠回原来的状态。这就是我们今天要学习的**文本展开折叠功能**。\\n\\n## 🎯 为什么需要文本展开折叠？\\n\\n### 应用场景\\n\\n- **社交媒体动态**：微博、朋友圈的长文本内容\\n- **评论系统**：博客、新闻下的用户评论\\n- **商品描述**：电商应用中的产品详情\\n- **文章摘要**：新闻应用的文章预览\\n\\n### 用户体验价值\\n\\n1. **节省屏幕空间**：避免长文本占据过多界面\\n2. **提升浏览效率**：用户可以快速浏览多条内容\\n3. **保持界面整洁**：统一的视觉呈现效果\\n\\n## 💡 技术挑战分析\\n\\n在 HarmonyOS 开发中，实现文本展开折叠功能面临以下技术难点：\\n\\n### 纯文本场景的挑战\\n\\n- 如何准确计算文本高度？\\n- 怎样确定截断位置？\\n- \\"...\\"和\\"展开\\"按钮如何定位？\\n\\n### 富文本场景的挑战（更复杂）\\n\\n- 包含表情图片的文本如何处理？\\n- 不同字号、颜色的文字混排\\n- 超链接等交互元素的处理\\n- 图片位置和大小不固定导致的计算复杂性\\n\\n![功能展示图](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250616113826.77667742245328129995240571158533:50001231000000:2800:0427A6283C0D14F9B954E8160DEA79DBB71973D28E39B361A61D797396E98A82.png)\\n\\n---\\n\\n## 📖 第一部分：纯文本展开折叠\\n\\n### 🎯 需求分析\\n\\n我们先从最简单的纯文本场景开始学习。这种场景的特点是：\\n\\n✅ **包含内容**：只有纯文字，无图片、表情等元素  \\n✅ **功能要求**：超过 3 行时显示\\"...展开\\"，点击展开后显示\\"收起\\"  \\n✅ **交互逻辑**：点击展开/收起按钮切换显示状态\\n\\n![纯文本效果图](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250616113826.17249976679089767759377396382962:50001231000000:2800:FA87708B612226678B9C52433D6F504DECCDC75553D7C3DF128440E5D47B9059.png)\\n\\n### 🔧 核心原理解析\\n\\n#### 基本思路\\n\\n想象你要在一本书的第 3 页末尾插入一个\\"展开\\"按钮，你需要知道：\\n\\n1. 📏 第 3 页能容纳多少文字？\\n2. 📍 最后一个文字的位置在哪里？\\n3. 🔘 按钮应该放在什么位置？\\n\\n![原理示意图](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250616113826.61912512751048200229944022412760:50001231000000:2800:AB5D8F0720D1777633EC87AB50A4BB6625A71325B7C04D09754A6CCF9FB2E92D.png)\\n\\n#### 计算逻辑\\n\\n1. **测量文本总高度** → 判断是否需要折叠\\n2. **计算指定行数的高度** → 确定截断位置\\n3. **计算截断点坐标** → 确定\\"...\\"的位置\\n4. **添加交互按钮** → 实现展开/收起功能\\n\\n### 🛠️ 详细实现步骤\\n\\n#### 步骤 1：计算原始文本高度\\n\\n```typescript\\n// 使用 HarmonyOS 提供的测量 API\\nimport measure from \\"@ohos.measure\\";\\n\\n// 测量完整文本的高度\\nconst fullTextHeight = measure.measureTextSize({\\n  textContent: originalText, // 原始文本内容\\n  fontSize: \\"16fp\\", // 字体大小\\n  fontFamily: \\"HarmonyOS Sans\\", // 字体家族\\n  constraintWidth: containerWidth, // 容器宽度限制\\n});\\n```\\n\\n**💡 新手提示**：`measureTextSize()` 是 HarmonyOS 提供的文本测量工具，就像用尺子测量文字的长度和高度一样。\\n\\n#### 步骤 2：计算收起状态的高度\\n\\n```typescript\\n// 计算指定行数（如3行）的高度\\nconst collapsedHeight = measure.measureTextSize({\\n  textContent: \\"测试文本\\\\n测试文本\\\\n测试文本\\", // 3行测试文本\\n  fontSize: \\"16fp\\",\\n  fontFamily: \\"HarmonyOS Sans\\",\\n  constraintWidth: containerWidth,\\n});\\n\\n// 判断是否需要显示展开按钮\\nconst needExpand = fullTextHeight.height > collapsedHeight.height;\\n```\\n\\n**💡 新手提示**：通过比较完整文本高度和限制行数高度，我们就知道是否需要添加\\"展开\\"功能。\\n\\n#### 步骤 3：计算截断文本内容\\n\\n```typescript\\n// 逐步减少文字，直到高度符合要求\\nfunction getCollapsedText(originalText: string, maxHeight: number): string {\\n  let text = originalText;\\n\\n  while (text.length > 0) {\\n    // 预留\\"...展开\\"按钮的空间\\n    const testText = text + \\"...展开\\";\\n    const textHeight = measure.measureTextSize({\\n      textContent: testText,\\n      fontSize: \\"16fp\\",\\n      fontFamily: \\"HarmonyOS Sans\\",\\n      constraintWidth: containerWidth,\\n    });\\n\\n    // 如果高度合适，返回截断后的文本\\n    if (textHeight.height <= maxHeight) {\\n      return text;\\n    }\\n\\n    // 继续减少文字\\n    text = text.substring(0, text.length - 1);\\n  }\\n\\n  return text;\\n}\\n```\\n\\n**💡 新手提示**：这个过程就像试衣服一样，一点点调整直到合适为止。\\n\\n#### 步骤 4：实现交互逻辑\\n\\n```typescript\\n@Entry\\n@Component\\nstruct TextExpandDemo {\\n  @State isExpanded: boolean = false;      // 展开状态\\n  @State displayText: string = \'\';         // 显示的文本\\n  private originalText: string = \'你的长文本内容...\';\\n  private collapsedText: string = \'\';      // 收起状态的文本\\n\\n  aboutToAppear() {\\n    // 计算收起状态的文本\\n    this.collapsedText = this.getCollapsedText(this.originalText);\\n    this.displayText = this.collapsedText;\\n  }\\n\\n  build() {\\n    Column() {\\n      // 显示文本\\n      Text(this.displayText)\\n        .fontSize(16)\\n        .fontFamily(\'HarmonyOS Sans\')\\n        .width(\'100%\')\\n\\n      // 展开/收起按钮\\n      if (!this.isExpanded && this.needExpandButton()) {\\n        Text(\'...展开\')\\n          .fontSize(16)\\n          .fontColor(Color.Blue)\\n          .onClick(() => {\\n            this.isExpanded = true;\\n            this.displayText = this.originalText;\\n          })\\n      } else if (this.isExpanded) {\\n        Text(\'收起\')\\n          .fontSize(16)\\n          .fontColor(Color.Blue)\\n          .onClick(() => {\\n            this.isExpanded = false;\\n            this.displayText = this.collapsedText;\\n          })\\n      }\\n    }\\n  }\\n}\\n```\\n\\n**💡 新手提示**：`@State` 装饰器让变量具有响应性，当值改变时界面会自动更新。\\n\\n---\\n\\n## 📚 第二部分：富文本展开折叠（进阶）\\n\\n### 🎯 场景分析\\n\\n富文本场景比纯文本复杂得多，包含以下元素：\\n\\n🎨 **多样化内容**\\n\\n- 表情图片（emoji）\\n- 不同颜色的文字\\n- 不同字号的文字\\n- 超链接等交互元素\\n\\n🔧 **技术难点**\\n\\n- 图片大小不固定\\n- 混合排版计算复杂\\n- 精确定位截断点困难\\n\\n![富文本效果图](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250616113826.36665665129508413766379546547350:50001231000000:2800:0DBA36FE8B3A99B820D2816EEF9A9714588BA454B6655DC8DEA47087721BAACB.png)\\n\\n### 🔧 高级原理解析\\n\\n富文本的处理就像排版一本杂志：\\n\\n- 📝 文字有不同的字体和颜色\\n- 🖼️ 图片需要占位和定位\\n- 📐 需要精确计算每个元素的位置\\n- ✂️ 在合适的位置进行\\"剪切\\"\\n\\n![富文本原理图](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20250616113826.35004406947813087056727115678538:50001231000000:2800:D4D378320333C9E5E811C94E78808E3FD3E9C04CD40E9C03BD570CE72338C8A3.png)\\n\\n### 🛠️ 高级实现步骤\\n\\n#### 步骤 1：引入图形文本处理模块\\n\\n```typescript\\nimport { graphics } from \\"@kit.ArkGraphics2D\\";\\n\\n// 引入必要的文本处理工具\\n// graphics.text 提供了强大的文本排版能力\\n```\\n\\n**💡 新手提示**：`graphics.text` 就像一个专业的排版工具，能够处理复杂的文本布局。\\n\\n#### 步骤 2：创建段落构建器\\n\\n```typescript\\n// 创建段落构建器和样式\\nconst style = new graphics.text.TextStyle();\\nstyle.color = Color.Black;\\nstyle.fontSize = vp2px(16); // 注意单位转换\\n\\nconst paragraphStyle = new graphics.text.ParagraphStyle();\\nparagraphStyle.textStyle = style;\\n\\nconst builder = new graphics.text.ParagraphBuilder(paragraphStyle);\\n```\\n\\n**💡 新手提示**：\\n\\n- `vp2px()` 用于单位转换（虚拟像素转物理像素）\\n- 需要考虑系统字体缩放设置\\n\\n#### 步骤 3：添加内容元素\\n\\n```typescript\\n// 遍历富文本内容数组\\nfor (let item of richTextArray) {\\n  if (item.type === \\"text\\") {\\n    // 添加文本\\n    if (item.color) {\\n      style.color = item.color;\\n      builder.pushStyle(style);\\n    }\\n\\n    builder.addText(item.content);\\n\\n    if (item.color) {\\n      builder.popStyle(); // 恢复之前的样式\\n    }\\n  } else if (item.type === \\"image\\") {\\n    // 添加图片占位符\\n    const placeholderStyle = new graphics.text.PlaceholderSpan();\\n    placeholderStyle.width = vp2px(item.width);\\n    placeholderStyle.height = vp2px(item.height);\\n    placeholderStyle.alignment = graphics.text.PlaceholderAlignment.BASELINE;\\n\\n    builder.addPlaceholder(placeholderStyle);\\n  }\\n}\\n```\\n\\n**💡 新手提示**：\\n\\n- `pushStyle()` 和 `popStyle()` 就像 CSS 的样式继承\\n- 图片用占位符表示，实际渲染时再替换\\n\\n#### 步骤 4：预排版计算\\n\\n```typescript\\n// 构建段落对象\\nconst paragraph = builder.build();\\n\\n// 进行预排版（重要！）\\nparagraph.layoutSync(containerWidth); // 宽度要与实际显示一致\\n\\n// 获取排版信息\\nconst lineCount = paragraph.getLineCount();\\nconst needCollapse = lineCount > maxLines;\\n```\\n\\n**💡 新手提示**：`layoutSync()` 就像提前彩排，让我们知道内容会如何显示。\\n\\n#### 步骤 5：计算精确截断位置\\n\\n```typescript\\nfunction calculateCutoffPosition(paragraph: graphics.text.Paragraph): number {\\n  // 计算\\"...展开\\"按钮占用的宽度\\n  const moreButtonWidth = measure.measureTextSize({\\n    textContent: \\"...展开\\",\\n    fontSize: \\"16fp\\",\\n  }).width;\\n\\n  // 计算最后一行可用宽度\\n  const lastLineY = 0;\\n  for (let i = 0; i < maxLines - 1; i++) {\\n    lastLineY += paragraph.getLineHeight(i);\\n  }\\n  lastLineY += paragraph.getLineHeight(maxLines - 1) / 2; // 最后一行中间位置\\n\\n  // 计算X坐标（需要为按钮预留空间）\\n  const lastLineX = containerWidth - moreButtonWidth;\\n\\n  // 根据坐标获取字符索引\\n  const position = paragraph.getGlyphPositionAtCoordinate(lastLineX, lastLineY);\\n\\n  return position.position; // 返回截断位置的字符索引\\n}\\n```\\n\\n**💡 新手提示**：这就像在地图上通过坐标找到具体位置一样。\\n\\n#### 步骤 6：实现完整的交互组件\\n\\n```typescript\\n@Entry\\n@Component\\nstruct RichTextExpandDemo {\\n  @State isExpanded: boolean = false;\\n  @State displayContent: Array<RichTextItem> = [];\\n  private originalContent: Array<RichTextItem> = [];  // 原始富文本数据\\n  private collapsedContent: Array<RichTextItem> = [];  // 收起状态数据\\n\\n  aboutToAppear() {\\n    this.processRichText();\\n  }\\n\\n  processRichText() {\\n    // 使用上述步骤计算截断位置\\n    const cutoffIndex = this.calculateCutoffPosition();\\n\\n    // 生成收起状态的内容数组\\n    this.collapsedContent = this.originalContent.slice(0, cutoffIndex);\\n    this.displayContent = this.collapsedContent;\\n  }\\n\\n  build() {\\n    Column() {\\n      // 渲染富文本内容\\n      ForEach(this.displayContent, (item: RichTextItem) => {\\n        if (item.type === \'text\') {\\n          Text(item.content)\\n            .fontSize(item.fontSize || 16)\\n            .fontColor(item.color || Color.Black)\\n        } else if (item.type === \'image\') {\\n          Image(item.src)\\n            .width(item.width)\\n            .height(item.height)\\n        }\\n      })\\n\\n      // 展开/收起按钮\\n      if (!this.isExpanded && this.needExpandButton()) {\\n        Row() {\\n          Text(\'...\')\\n          Text(\'展开\')\\n            .fontColor(Color.Blue)\\n            .onClick(() => this.expandText())\\n        }\\n      } else if (this.isExpanded) {\\n        Text(\'收起\')\\n          .fontColor(Color.Blue)\\n          .onClick(() => this.collapseText())\\n      }\\n    }\\n  }\\n\\n  expandText() {\\n    this.isExpanded = true;\\n    this.displayContent = this.originalContent;\\n  }\\n\\n  collapseText() {\\n    this.isExpanded = false;\\n    this.displayContent = this.collapsedContent;\\n  }\\n}\\n```\\n\\n---\\n\\n## 🎯 关键技术要点总结\\n\\n### 纯文本方案\\n\\n✅ **适用场景**：简单的文字内容展开折叠  \\n✅ **核心 API**：`measure.measureTextSize()`  \\n✅ **计算方式**：文本高度比较 + 字符串截断  \\n✅ **难度等级**：⭐⭐⭐\\n\\n### 富文本方案\\n\\n✅ **适用场景**：包含图片、多样式文字的复杂内容  \\n✅ **核心 API**：`graphics.text` 系列接口  \\n✅ **计算方式**：预排版 + 坐标转换 + 精确定位  \\n✅ **难度等级**：⭐⭐⭐⭐⭐\\n\\n## ⚠️ 开发注意事项\\n\\n### 性能优化\\n\\n1. **避免频繁计算**：缓存计算结果\\n2. **合理使用预排版**：只在必要时进行计算\\n3. **内存管理**：及时释放不用的对象\\n\\n### 兼容性考虑\\n\\n1. **字体缩放**：适配系统字体大小设置\\n2. **屏幕适配**：考虑不同屏幕密度\\n3. **主题适配**：支持深色模式等主题切换\\n\\n### 用户体验\\n\\n1. **动画效果**：添加平滑的展开收起动画\\n2. **加载状态**：长文本处理时显示加载提示\\n3. **无障碍支持**：添加合适的无障碍描述\\n\\n## 🚀 进阶扩展\\n\\n学会了基础实现后，你还可以尝试：\\n\\n1. **添加渐变遮罩效果**：让收起状态更自然\\n2. **支持多种展开方式**：点击、滑动、长按等\\n3. **智能截断优化**：避免在词语中间截断\\n4. **自定义按钮样式**：更丰富的视觉效果\\n\\n## 💭 总结\\n\\n文本展开折叠功能看似简单，实际包含了很多细节处理。通过本文的学习，你应该能够：\\n\\n1. 理解文本展开折叠的应用场景和价值\\n2. 掌握纯文本场景的实现方法\\n3. 了解富文本场景的处理思路\\n4. 具备解决相关问题的能力\\n\\n记住，好的用户体验往往来自于对细节的精心雕琢。希望这篇文章能帮助你在 HarmonyOS 开发路上更进一步！\\n\\n---\\n\\n> 💡 **学习建议**：建议先从纯文本方案开始实践，熟练后再挑战富文本方案。每个步骤都可以单独验证，这样更容易定位和解决问题。\\n"}'),p={name:"HarmonyOS 最佳实践/14-文本展开折叠/14-文本展开折叠.md"};function t(e,s,h,k,r,E){return n(),a("div",null,[...s[0]||(s[0]=[l("",96)])])}const c=i(p,[["render",t]]);export{g as __pageData,c as default};
